import {
  app,
  BrowserWindow,
  dialog,
  type Event as ElectronEvent,
} from "electron";

import { createRuntimeConfig, type RuntimeConfig } from "./runtime-config.js";
import {
  DesktopRuntimeError,
  ServerProcess,
} from "./server-process.js";

let mainWindow: BrowserWindow | null = null;
let serverProcess: ServerProcess | null = null;
let runtimeConfig: RuntimeConfig | null = null;
let isQuitting = false;
let startupPromise: Promise<void> | null = null;
let isStarting = false;

export function isAllowedNavigation(origin: string, url: string): boolean {
  try {
    return new URL(url).origin === origin;
  } catch {
    return false;
  }
}

function focusMainWindow(): void {
  if (!mainWindow) {
    return;
  }
  if (mainWindow.isMinimized()) {
    mainWindow.restore();
  }
  mainWindow.focus();
}

function configureWindowSecurity(window: BrowserWindow, origin: string): void {
  const denyNavigation = (event: ElectronEvent, url: string) => {
    if (!isAllowedNavigation(origin, url)) {
      event.preventDefault();
    }
  };

  window.webContents.on("will-navigate", denyNavigation);
  window.webContents.on("will-redirect", denyNavigation);
  window.webContents.setWindowOpenHandler(() => ({ action: "deny" }));
}

async function createMainWindow(): Promise<void> {
  if (!runtimeConfig || !serverProcess?.isReady) {
    throw new Error("The desktop server is not ready for a window");
  }

  mainWindow = new BrowserWindow({
    show: false,
    width: 1280,
    height: 860,
    minWidth: 960,
    minHeight: 640,
    title: "NamehAmal",
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      sandbox: true,
    },
  });
  configureWindowSecurity(mainWindow, runtimeConfig.origin);
  mainWindow.on("closed", () => {
    mainWindow = null;
  });

  try {
    await mainWindow.loadURL(runtimeConfig.origin);
    mainWindow.show();
  } catch (error) {
    mainWindow.destroy();
    mainWindow = null;
    throw new DesktopRuntimeError(
      "SERVER_CRASHED",
      `NamehAmal could not load its local dashboard. Check ${serverProcess.logPath ?? "the desktop log"} and try again.`,
      { cause: error },
    );
  }
}

function showStartupError(error: unknown): void {
  const message =
    error instanceof Error
      ? error.message
      : "The desktop application could not start for an unknown reason.";
  dialog.showErrorBox("NamehAmal could not start", message);
}

async function startApplication(): Promise<void> {
  isStarting = true;
  runtimeConfig = createRuntimeConfig({
    isPackaged: app.isPackaged,
    projectRoot: app.getAppPath(),
    resourcesPath: process.resourcesPath,
    userDataDirectory: app.getPath("userData"),
  });
  serverProcess = new ServerProcess({
    config: runtimeConfig,
    onUnexpectedExit: (error) => {
      if (isQuitting) {
        return;
      }
      showStartupError(error);
      app.quit();
    },
  });
  try {
    await serverProcess.start();
    await createMainWindow();
  } finally {
    isStarting = false;
  }
}

async function shutdown(): Promise<void> {
  await serverProcess?.stop();
  serverProcess = null;
}

const gotSingleInstanceLock = app.requestSingleInstanceLock();

if (!gotSingleInstanceLock) {
  app.quit();
} else {
  app.on("second-instance", () => {
    focusMainWindow();
  });

  app.whenReady().then(() => {
    startupPromise = startApplication().catch((error) => {
      showStartupError(error);
      void app.quit();
    });
    return startupPromise;
  });

  app.on("activate", () => {
    if (mainWindow) {
      focusMainWindow();
      return;
    }
    if (serverProcess?.isReady && !isStarting) {
      startupPromise = createMainWindow().catch((error) => {
        showStartupError(error);
        void app.quit();
      });
    }
  });

  app.on("window-all-closed", () => {
    if (!isQuitting) {
      app.quit();
    }
  });

  app.on("before-quit", (event) => {
    if (isQuitting) {
      return;
    }
    event.preventDefault();
    isQuitting = true;
    void shutdown().finally(() => {
      app.quit();
    });
  });
}

"use client";

import { type FormEvent, useState } from "react";
import {
  formatPomodoroCountdown,
  minutesToSeconds,
  secondsToMinutes,
} from "@/app/lib/pomodoro/format";
import { PHASE_LABELS } from "@/app/lib/pomodoro/phase-labels";
import { usePomodoro } from "@/app/lib/pomodoro/use-pomodoro";

function settingsToFormValues(settings: {
  focusSeconds: number;
  shortRestSeconds: number;
  longRestSeconds: number;
  longRestInterval: number;
}) {
  return {
    focusMinutes: String(secondsToMinutes(settings.focusSeconds)),
    shortRestMinutes: String(secondsToMinutes(settings.shortRestSeconds)),
    longRestMinutes: String(secondsToMinutes(settings.longRestSeconds)),
    longRestInterval: String(settings.longRestInterval),
  };
}

export function PomodoroView() {
  const {
    state,
    isHydrated,
    start,
    stop,
    skip,
    updateSettings,
    notificationStatus,
    requestNotificationPermission,
  } = usePomodoro();
  const [form, setForm] = useState(() => settingsToFormValues(state.settings));
  const [savedAt, setSavedAt] = useState<number | null>(null);
  const [notificationRequestPending, setNotificationRequestPending] =
    useState(false);

  if (!isHydrated) {
    return (
      <div className="rounded-xl border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-black">
        <div className="text-center text-sm text-zinc-500 dark:text-zinc-400">
          Loading Pomodoro…
        </div>
      </div>
    );
  }

  function onSubmitSettings(e: FormEvent) {
    e.preventDefault();

    const focusMinutes = Number(form.focusMinutes);
    const shortRestMinutes = Number(form.shortRestMinutes);
    const longRestMinutes = Number(form.longRestMinutes);
    const longRestInterval = Number(form.longRestInterval);

    if (
      !Number.isFinite(focusMinutes) ||
      !Number.isFinite(shortRestMinutes) ||
      !Number.isFinite(longRestMinutes) ||
      !Number.isFinite(longRestInterval) ||
      focusMinutes <= 0 ||
      shortRestMinutes <= 0 ||
      longRestMinutes <= 0 ||
      longRestInterval <= 0
    ) {
      return;
    }

    updateSettings({
      focusSeconds: minutesToSeconds(focusMinutes),
      shortRestSeconds: minutesToSeconds(shortRestMinutes),
      longRestSeconds: minutesToSeconds(longRestMinutes),
      longRestInterval: Math.floor(longRestInterval),
    });
    setSavedAt(Date.now());
  }

  async function onNotificationToggle() {
    if (state.settings.notifyOnPhaseComplete) {
      updateSettings({ notifyOnPhaseComplete: false });
      return;
    }

    updateSettings({ notifyOnPhaseComplete: true });
    setNotificationRequestPending(true);
    try {
      await requestNotificationPermission();
    } finally {
      setNotificationRequestPending(false);
    }
  }

  const isIdle = state.phase === "idle";
  const isRunning = state.isRunning;
  const notificationMessage =
    notificationStatus === "unsupported"
      ? "Browser alerts are not available. The in-page alert and sound still work."
      : notificationStatus === "denied" || notificationStatus === "error"
        ? "Browser alerts are blocked. The in-page alert and sound still work."
        : state.settings.notifyOnPhaseComplete && notificationStatus !== "granted"
          ? "Allow browser alerts to receive phase-end notices in another tab."
          : null;

  return (
