export type PomodoroPhase = "idle" | "focus" | "short_rest" | "long_rest";

export type PomodoroSettings = {
  focusSeconds: number;
  shortRestSeconds: number;
  longRestSeconds: number;
  longRestInterval: number;
  notifyOnPhaseComplete: boolean;
};

export const DEFAULT_POMODORO_SETTINGS: PomodoroSettings = {
  focusSeconds: 25 * 60,
  shortRestSeconds: 5 * 60,
  longRestSeconds: 15 * 60,
  longRestInterval: 4,
  notifyOnPhaseComplete: false,
};

export type PomodoroNotificationStatus =
  | "default"
  | "granted"
  | "denied"
  | "unsupported"
  | "error";

export type PomodoroState = {
  phase: PomodoroPhase;
  remainingSeconds: number;
  phaseEndsAtMs: number | null;
  isRunning: boolean;
  completedFocusSessions: number;
  settings: PomodoroSettings;
};

export type ActivePomodoroPhase = Exclude<PomodoroPhase, "idle">;

import {
  DEFAULT_POMODORO_SETTINGS,
  type ActivePomodoroPhase,
  type PomodoroPhase,
  type PomodoroSettings,
  type PomodoroState,
} from "./types";

export type PhaseTransitionResult = {
  state: PomodoroState;
  phaseCompleted: ActivePomodoroPhase | null;
};

export function getPhaseDuration(
  phase: PomodoroPhase,
  settings: PomodoroSettings,
): number {
  switch (phase) {
    case "focus":
      return settings.focusSeconds;
    case "short_rest":
      return settings.shortRestSeconds;
    case "long_rest":
      return settings.longRestSeconds;
    case "idle":
      return settings.focusSeconds;
  }
}

export function createInitialState(
  settings: PomodoroSettings = DEFAULT_POMODORO_SETTINGS,
): PomodoroState {
  return {
    phase: "idle",
    remainingSeconds: settings.focusSeconds,
    phaseEndsAtMs: null,
    isRunning: false,
    completedFocusSessions: 0,
    settings: { ...settings },
  };
}

export function start(state: PomodoroState, now = Date.now()): PomodoroState {
  if (state.isRunning) return state;

  if (state.phase === "idle") {
    const remainingSeconds = state.settings.focusSeconds;
    return {
      ...state,
      phase: "focus",
      remainingSeconds,
      phaseEndsAtMs: now + remainingSeconds * 1000,
      isRunning: true,
    };
  }

  return {
    ...state,
    phaseEndsAtMs: now + state.remainingSeconds * 1000,
    isRunning: true,
  };
}

/** Cancel the current run and return to idle without changing settings or cadence. */
export function stop(state: PomodoroState): PomodoroState {
  return {
    ...state,
    phase: "idle",
    remainingSeconds: state.settings.focusSeconds,
    phaseEndsAtMs: null,
    isRunning: false,
  };
}

function advanceAfterPhase(
  state: PomodoroState,
  completedPhase: ActivePomodoroPhase,
): PomodoroState {
  if (completedPhase === "focus") {
    const completedFocusSessions = state.completedFocusSessions + 1;
    const useLongRest =
      completedFocusSessions % state.settings.longRestInterval === 0;
    const nextPhase = useLongRest ? "long_rest" : "short_rest";

    return {
      ...state,
      phase: nextPhase,
      remainingSeconds: getPhaseDuration(nextPhase, state.settings),
      phaseEndsAtMs: null,
      isRunning: false,
      completedFocusSessions,
    };
  }

  const resetCadence = completedPhase === "long_rest";

  return {
    ...state,
    phase: "focus",
    remainingSeconds: state.settings.focusSeconds,
    phaseEndsAtMs: null,
    isRunning: false,
    completedFocusSessions: resetCadence ? 0 : state.completedFocusSessions,
  };
}

function completeCurrentPhase(state: PomodoroState): PhaseTransitionResult {
  if (state.phase === "idle") {
    return { state, phaseCompleted: null };
  }

  const completedPhase = state.phase;
  return {
    state: advanceAfterPhase(state, completedPhase),
    phaseCompleted: completedPhase,
  };
}

export function skip(state: PomodoroState): PhaseTransitionResult {
  if (state.phase === "idle") {
    return { state, phaseCompleted: null };
  }

  return completeCurrentPhase({ ...state, isRunning: false, phaseEndsAtMs: null });
}

export function tick(state: PomodoroState, now = Date.now()): PhaseTransitionResult {
  if (!state.isRunning || state.phase === "idle") {
    return { state, phaseCompleted: null };
  }

  if (state.phaseEndsAtMs === null) {
    return {
      state: {
        ...state,
        phaseEndsAtMs: now + state.remainingSeconds * 1000,
      },
      phaseCompleted: null,
    };
  }

  if (now < state.phaseEndsAtMs) {
    return {
      state: {
        ...state,
        remainingSeconds: Math.max(
          1,
          Math.ceil((state.phaseEndsAtMs - now) / 1000),
        ),
      },
      phaseCompleted: null,
    };
  }

  return completeCurrentPhase({
    ...state,
    remainingSeconds: 0,
    isRunning: false,
    phaseEndsAtMs: null,
  });
}

/** Reconcile a saved run with the current clock when a tab opens or syncs. */
export function hydratePomodoroState(
  state: PomodoroState,
  now = Date.now(),
): PhaseTransitionResult {
  return tick(state, now);
}

/** Apply settings on the next phase; does not change the current countdown while running. */
export function updateSettings(
  state: PomodoroState,
  partial: Partial<PomodoroSettings>,
): PomodoroState {
  const settings = { ...state.settings, ...partial };

  if (state.isRunning || state.phase !== "idle") {
    return { ...state, settings };
  }

  return {
    ...state,
    settings,
    remainingSeconds: settings.focusSeconds,
    phaseEndsAtMs: null,
  };
}

"use client";

import {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import {
  createInitialState,
  hydratePomodoroState,
  skip,
  start,
  stop,
  tick,
  updateSettings,
} from "./engine";
import {
  loadPomodoroRun,
  loadPomodoroSettings,
  RUN_KEY,
  savePomodoroRun,
  savePomodoroSettings,
} from "./storage";
import {
  getPomodoroNotificationStatus,
  requestPomodoroNotificationPermission,
} from "./notifications";
import type {
  ActivePomodoroPhase,
  PomodoroNotificationStatus,
  PomodoroPhase,
  PomodoroSettings,
  PomodoroState,
} from "./types";
import { PomodoroPhaseAlert } from "./PomodoroPhaseAlert";
import { PomodoroPhaseNotification } from "./PomodoroPhaseNotification";

const subscribeToHydration = () => () => {};
const getHydratedSnapshot = () => true;
const getServerHydratedSnapshot = () => false;

type PomodoroContextValue = {
  state: PomodoroState;
  isHydrated: boolean;
  start: () => void;
  stop: () => void;
  skip: () => void;
  updateSettings: (partial: Partial<PomodoroSettings>) => void;
  notificationStatus: PomodoroNotificationStatus;
  requestNotificationPermission: () => Promise<PomodoroNotificationStatus>;
  reportNotificationFailure: () => void;
  subscribePhaseComplete: (
    fn: (phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => void,
  ) => () => void;
};

export const PomodoroContext = createContext<PomodoroContextValue | null>(null);

type InitialPomodoroState = {
  state: PomodoroState;
  phaseCompleted: ActivePomodoroPhase | null;
};

export function PomodoroProvider({ children }: { children: ReactNode }) {
  const isHydrated = useSyncExternalStore(
    subscribeToHydration,
    getHydratedSnapshot,
    getServerHydratedSnapshot,
  );
  const [initialState] = useState<InitialPomodoroState>(() => {
    const settings = loadPomodoroSettings();
    const loaded = loadPomodoroRun(settings);
    return hydratePomodoroState(loaded, Date.now());
  });
  const [state, setState] = useState<PomodoroState>(initialState.state);
  const [notificationStatus, setNotificationStatus] =
    useState<PomodoroNotificationStatus>(() => getPomodoroNotificationStatus());
  const initialPhaseCompletion = useRef(
    initialState.phaseCompleted
      ? {
          completedPhase: initialState.phaseCompleted,
          nextPhase: initialState.state.phase,
        }
      : null,
  );
  const phaseCompleteListeners = useRef(
    new Set<(phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => void>(),
  );

  useEffect(() => {
    savePomodoroSettings(state.settings);
  }, [state.settings]);

  useEffect(() => {
    savePomodoroRun(state);
  }, [state]);

  const emitPhaseComplete = useCallback(
    (phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => {
      for (const fn of phaseCompleteListeners.current) fn(phase, nextPhase);
    },
    [],
  );

  useEffect(() => {
    const completion = initialPhaseCompletion.current;
    if (!completion) return;

    initialPhaseCompletion.current = null;
    queueMicrotask(() =>
      emitPhaseComplete(completion.completedPhase, completion.nextPhase),
    );
  }, [emitPhaseComplete]);

  useEffect(() => {
    if (!state.isRunning) return;

    const id = window.setInterval(() => {
      setState((current) => {
        const result = tick(current, Date.now());
        if (result.phaseCompleted) {
          queueMicrotask(() =>
            emitPhaseComplete(result.phaseCompleted!, result.state.phase),
          );
        }
        return result.state;
      });
    }, 1000);

    return () => window.clearInterval(id);
  }, [state.isRunning, emitPhaseComplete]);

  useEffect(() => {
    function handleStorage(event: StorageEvent) {
      if (event.key !== RUN_KEY) return;

      const settings = loadPomodoroSettings();
      const incoming = event.newValue
        ? loadPomodoroRun(settings)
        : createInitialState(settings);
      const result = hydratePomodoroState(incoming, Date.now());

      if (result.phaseCompleted) {
        queueMicrotask(() =>
          emitPhaseComplete(result.phaseCompleted!, result.state.phase),
        );
      }
      setState(result.state);
    }

    window.addEventListener("storage", handleStorage);
    return () => window.removeEventListener("storage", handleStorage);
  }, [emitPhaseComplete]);

  const handleStart = useCallback(() => {
    setState((current) => {
      return start(current);
    });
  }, []);

  const handleStop = useCallback(() => {
    setState((current) => {
      return stop(current);
    });
  }, []);

  const handleSkip = useCallback(() => {
    setState((current) => skip(current).state);
  }, []);

  const handleUpdateSettings = useCallback((partial: Partial<PomodoroSettings>) => {
    setState((current) => updateSettings(current, partial));
  }, []);

  const handleRequestNotificationPermission = useCallback(async () => {
    const status = await requestPomodoroNotificationPermission();
    setNotificationStatus(status);
    return status;
  }, []);

  const reportNotificationFailure = useCallback(() => {
    setNotificationStatus("error");
  }, []);

  const subscribePhaseComplete = useCallback(
    (fn: (phase: ActivePomodoroPhase, nextPhase: PomodoroPhase) => void) => {
      phaseCompleteListeners.current.add(fn);
      return () => {
        phaseCompleteListeners.current.delete(fn);
      };
    },
    [],
  );

  const value = useMemo(
    () => ({
      state,
      isHydrated,
      start: handleStart,
      stop: handleStop,
      skip: handleSkip,
      updateSettings: handleUpdateSettings,
      notificationStatus,
      requestNotificationPermission: handleRequestNotificationPermission,
      reportNotificationFailure,
      subscribePhaseComplete,
    }),
    [
      state,
      isHydrated,
      handleStart,
      handleStop,
      handleSkip,
      handleUpdateSettings,
      notificationStatus,
      handleRequestNotificationPermission,
      reportNotificationFailure,
      subscribePhaseComplete,
    ],
  );

  return (
    <PomodoroContext.Provider value={value}>
      <PomodoroPhaseNotification />
      <PomodoroPhaseAlert />
      {children}
    </PomodoroContext.Provider>
  );
}

"use client";

import { type FormEvent, useEffect, useMemo, useState } from "react";
import type { CategoryModel } from "@/app/generated/prisma/models";
import { ActivityCombobox, type ActivitySelection } from "@/app/components/ActivityCombobox";
import { toActivitySelection } from "@/app/lib/use-activities";
import { ActivityFormDialog } from "@/app/settings/ActivityFormDialog";
import { fetchCategories, fetchDefaultTimeZone } from "@/app/lib/tracker-client";

export type CheckInSubmitPayload = {
  categoryId: string;
  title: string | null;
  timeZone: string;
};

const inputClassName =
  "h-10 w-full rounded-lg border border-zinc-200 bg-white px-3 text-sm text-zinc-900 outline-none focus:ring-2 focus:ring-zinc-400 dark:border-zinc-800 dark:bg-black dark:text-zinc-50";

// Compact activity form used inside the Pomodoro phase-complete check-in.
export function ActivityCheckInForm({
  submitLabel,
  busyLabel,
  busy,
  error,
  onSubmit,
  onCancel,
  cancelLabel,
  secondary,
}: {
  submitLabel: string;
  busyLabel: string;
  busy: boolean;
  error: string | null;
  onSubmit: (payload: CheckInSubmitPayload) => void;
  onCancel: () => void;
  cancelLabel: string;
  secondary?: React.ReactNode;
}) {
  const [categories, setCategories] = useState<CategoryModel[] | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [timeZone, setTimeZone] = useState("Asia/Yerevan");
  const [categoryId, setCategoryId] = useState("");
  const [title, setTitle] = useState("");
  const [activityQuery, setActivityQuery] = useState("");
  const [createActivityOpen, setCreateActivityOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;
    Promise.all([fetchCategories(), fetchDefaultTimeZone()])
      .then(([nextCategories, nextTimeZone]) => {
        if (cancelled) return;
        setCategories(nextCategories);
        setCategoryId((current) => current || nextCategories[0]?.id || "");
        setTimeZone(nextTimeZone);
      })
      .catch((err) => {
        if (cancelled) return;
        setLoadError(err instanceof Error ? err.message : "Failed to load form data.");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const defaultCategoryId = useMemo(
    () => categories?.[0]?.id ?? "",
    [categories],
  );

  function applyActivitySelection(activity: ActivitySelection) {
    setTitle(activity.title);
    setCategoryId(activity.categoryId);
    setActivityQuery(activity.title);
  }

  function clearActivityPrefill() {
    setTitle("");
    setCategoryId(defaultCategoryId);
    setActivityQuery("");
  }

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!categoryId) return;
    onSubmit({
      categoryId,
      title: title.trim() ? title.trim() : null,
      timeZone,
    });
  }

  const displayedError = error ?? loadError;
  const noCategories = categories !== null && categories.length === 0;

  return (
    <form onSubmit={handleSubmit} className="mt-4 flex flex-col gap-3">
      <div className="flex flex-col gap-1.5">
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Activity
        </label>
        <ActivityCombobox
          value={activityQuery}
          onValueChange={(next) => {
            setActivityQuery(next);
            if (!next.trim()) clearActivityPrefill();
          }}
          onSelect={applyActivitySelection}
          onClear={clearActivityPrefill}
          onCreateNew={() => setCreateActivityOpen(true)}
          placeholder="Search activities to pre-fill…"
          disabled={busy}
        />
      </div>

      <div className="flex flex-col gap-1.5">
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Category
        </label>
        <select
          value={categoryId}
          onChange={(e) => setCategoryId(e.target.value)}
          className={inputClassName}
          disabled={busy || categories === null}
        >
          {categories === null ? <option value="">Loading…</option> : null}
          {noCategories ? <option value="">No active categories</option> : null}
          {(categories ?? []).map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
      </div>

      <div className="flex flex-col gap-1.5">
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Title
        </label>
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Optional"
          className={inputClassName}
          disabled={busy}
        />
      </div>

      {noCategories ? (
        <p className="text-xs text-amber-700 dark:text-amber-300">
          Create a category in Settings before recording an activity.
        </p>
      ) : null}

      {displayedError ? (
        <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-800 dark:border-red-900 dark:bg-red-950 dark:text-red-200">
          {displayedError}
        </div>
      ) : null}

      <div className="flex flex-wrap items-center gap-2">
        <button
          type="submit"
          disabled={busy || !categoryId}
          className="inline-flex h-10 items-center justify-center rounded-lg bg-zinc-900 px-4 text-sm font-medium text-white hover:bg-zinc-800 disabled:opacity-50 dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-200"
        >
          {busy ? busyLabel : submitLabel}
        </button>
        <button
          type="button"
          onClick={onCancel}
          disabled={busy}
          className="inline-flex h-10 items-center justify-center rounded-lg border border-zinc-300 px-4 text-sm font-medium text-zinc-800 hover:bg-zinc-50 disabled:opacity-50 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-950"
        >
          {cancelLabel}
        </button>
        {secondary}
      </div>

      <ActivityFormDialog
        open={createActivityOpen}
        onClose={() => setCreateActivityOpen(false)}
        categories={categories ?? []}
        initialTitle={activityQuery.trim() || undefined}
        onSuccess={(activity) => applyActivitySelection(toActivitySelection(activity))}
      />
    </form>
  );
}

import {
  DEFAULT_POMODORO_SETTINGS,
  type PomodoroPhase,
  type PomodoroSettings,
  type PomodoroState,
} from "./types";
import { createInitialState } from "./engine";

const SETTINGS_KEY = "nameh-amal:pomodoro:settings";
export const RUN_KEY = "nameh-amal:pomodoro:run";

export type PomodoroRunSnapshot = Pick<
  PomodoroState,
  | "phase"
  | "remainingSeconds"
  | "isRunning"
  | "completedFocusSessions"
  | "phaseEndsAtMs"
>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readPositiveInt(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? Math.floor(value)
    : fallback;
}

function readNonNegativeInt(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0
    ? Math.floor(value)
    : fallback;
}

/** Parse persisted settings; falls back to defaults for invalid or missing data. */
export function parsePomodoroSettings(raw: unknown): PomodoroSettings {
  if (!isRecord(raw)) return { ...DEFAULT_POMODORO_SETTINGS };

  return {
    focusSeconds: readPositiveInt(
      raw.focusSeconds,
      DEFAULT_POMODORO_SETTINGS.focusSeconds,
    ),
    shortRestSeconds: readPositiveInt(
      raw.shortRestSeconds,
      DEFAULT_POMODORO_SETTINGS.shortRestSeconds,
    ),
    longRestSeconds: readPositiveInt(
      raw.longRestSeconds,
      DEFAULT_POMODORO_SETTINGS.longRestSeconds,
    ),
    longRestInterval: readPositiveInt(
      raw.longRestInterval,
      DEFAULT_POMODORO_SETTINGS.longRestInterval,
    ),
    notifyOnPhaseComplete: raw.notifyOnPhaseComplete === true,
  };
}

/** Load settings from localStorage (client only). */
export function loadPomodoroSettings(): PomodoroSettings {
  if (typeof window === "undefined") return { ...DEFAULT_POMODORO_SETTINGS };

  try {
    const raw = window.localStorage.getItem(SETTINGS_KEY);
    if (!raw) return { ...DEFAULT_POMODORO_SETTINGS };
    return parsePomodoroSettings(JSON.parse(raw));
  } catch {
    return { ...DEFAULT_POMODORO_SETTINGS };
  }
}

/** Persist settings to localStorage. */
export function savePomodoroSettings(settings: PomodoroSettings): void {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
}

function isPomodoroPhase(value: unknown): value is PomodoroPhase {
  return (
    value === "idle" ||
    value === "focus" ||
    value === "short_rest" ||
    value === "long_rest"
  );
}

function isValidPhaseEnd(value: unknown): value is number | null {
  return value === null || (typeof value === "number" && Number.isFinite(value));
}

/** Parse a saved run; invalid data falls back to an idle state. */
export function parsePomodoroRun(
  raw: unknown,
  settings: PomodoroSettings = DEFAULT_POMODORO_SETTINGS,
): PomodoroState {
  const fallback = createInitialState(settings);
  if (!isRecord(raw)) return fallback;

  const phase = raw.phase;
  const isRunning = raw.isRunning;
  const phaseEndsAtMs = raw.phaseEndsAtMs;

  if (
    !isPomodoroPhase(phase) ||
    typeof isRunning !== "boolean" ||
    !isValidPhaseEnd(phaseEndsAtMs)
  ) {
    return fallback;
  }

  const remainingSeconds = readPositiveInt(raw.remainingSeconds, 0);
  const completedFocusSessions = readNonNegativeInt(
    raw.completedFocusSessions,
    0,
  );

  if (remainingSeconds === 0) return fallback;
  if (phase === "idle" && (isRunning || phaseEndsAtMs !== null)) return fallback;
  if (phase !== "idle" && isRunning === (phaseEndsAtMs === null)) return fallback;

  return {
    ...fallback,
    phase,
    remainingSeconds,
    isRunning,
    completedFocusSessions,
    phaseEndsAtMs,
  };
}

/** Load the saved Pomodoro run from localStorage (client only). */
export function loadPomodoroRun(
  settings: PomodoroSettings = DEFAULT_POMODORO_SETTINGS,
): PomodoroState {
  if (typeof window === "undefined") return createInitialState(settings);

  try {
    const raw = window.localStorage.getItem(RUN_KEY);
    if (!raw) return createInitialState(settings);
    return parsePomodoroRun(JSON.parse(raw), settings);
  } catch {
    return createInitialState(settings);
  }
}

/** Persist the current Pomodoro run to localStorage. */
export function savePomodoroRun(state: PomodoroState): void {
  if (typeof window === "undefined") return;

  const snapshot: PomodoroRunSnapshot = {
    phase: state.phase,
    remainingSeconds: state.remainingSeconds,
    isRunning: state.isRunning,
    completedFocusSessions: state.completedFocusSessions,
    phaseEndsAtMs: state.phaseEndsAtMs,
  };
  window.localStorage.setItem(RUN_KEY, JSON.stringify(snapshot));
}

"use client";

import type { CategoryModel, SessionModel } from "@/app/generated/prisma/models";

export type SessionWithCategory = SessionModel & { category: CategoryModel };

type SettingsResponse =
  | { ok: true; data: { id: string; timeZone: string } }
  | { ok: false; error: string };

export type StartTimerPayload = {
  categoryId: string;
  title: string | null;
  timeZone: string;
  startedAt?: string;
};

/** Raised when the server rejects a start because another timer is already running. */
export class ActiveTimerConflictError extends Error {
  readonly active: SessionWithCategory;

  constructor(active: SessionWithCategory) {
    super("A timer session is already running.");
    this.name = "ActiveTimerConflictError";
    this.active = active;
  }
}

// Fetch the currently active timer session (if any).
export async function fetchActiveTimer(): Promise<SessionWithCategory | null> {
  const res = await fetch("/api/tracker", { cache: "no-store" });
  const json = (await res.json()) as {
    ok: boolean;
    data: SessionWithCategory | null;
    error?: string;
  };
  if (!res.ok || !json.ok) {
    throw new Error(json.error || `Failed to fetch active timer (${res.status}).`);
  }
  return json.data ?? null;
}

// Fetch the app's default timezone setting.
export async function fetchDefaultTimeZone(): Promise<string> {
  const res = await fetch("/api/settings", { cache: "no-store" });
  const json = (await res.json()) as SettingsResponse;
  if (!res.ok || !json.ok) {
    throw new Error(!json.ok ? json.error : `Failed to load settings (${res.status}).`);
  }
  return json.data.timeZone || "Asia/Yerevan";
}

// Fetch selectable (non-archived) categories.
export async function fetchCategories(): Promise<CategoryModel[]> {
  const res = await fetch("/api/categories", { cache: "no-store" });
  const json = (await res.json()) as {
    ok: boolean;
    data?: CategoryModel[];
    error?: string;
  };
  if (!res.ok || !json.ok) {
    throw new Error(json.error || `Failed to load categories (${res.status}).`);
  }
  return json.data ?? [];
}

// Start a new timer session (optional `startedAt` ISO for backdated start).
export async function startTimer(
  payload: StartTimerPayload,
): Promise<SessionWithCategory> {
  const res = await fetch("/api/tracker", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ action: "start", ...payload }),
  });
  const json = (await res.json()) as {
    ok: boolean;
    data?: SessionWithCategory;
    error?: string;
  };
  if (res.status === 409 && json.data) {
    throw new ActiveTimerConflictError(json.data);
  }
  if (!res.ok || !json.ok || !json.data) {
    throw new Error(json.error || `Failed to start timer (${res.status}).`);
  }
  return json.data;
}

// Stop the currently running timer session (finalizes it into a Session row).
export async function stopTimer(sessionId: string): Promise<void> {
  const res = await fetch("/api/tracker", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ action: "stop", sessionId }),
  });
  const json = (await res.json()) as { ok: boolean; error?: string };
  if (!res.ok || !json.ok) {
    throw new Error(json.error || `Failed to stop timer (${res.status}).`);
  }
}

// Stop the running timer, then immediately start a new one for the chosen activity.
export async function switchTimer(
  activeSessionId: string,
  payload: StartTimerPayload,
): Promise<SessionWithCategory> {
  await stopTimer(activeSessionId);
  return startTimer(payload);
}

